mapper.select:
  SELECT p.id as post_id, p.user_id, p.title, p.content, p.created_at as post_created_at,
  u.email, u.nickname, u.created_at as user_created_at
FROM users u
INNER JOIN posts p ON u.id = p.user_id
WHERE p.id = #{id}
ORDER BY post_id DESC;
LIMIT #{offset}, #{size}

mapper.update:
UPDATE posts
SET title = #{title},
    content = #{content}
WHERE id = #{id}
